async function trc20Balance(address, coin2) {
  const data = await post("/wallet/triggerconstantcontract", {
    owner_address: hexAddress(address),
    contract_address: hexAddress(coin2.address),
    function_selector: "balanceOf(address)",
    parameter: padParameter(address),
    visible: false
  });
  const hex = data?.constant_result?.[0];
  if (!hex) return 0;
  return Number(BigInt(`0x${hex}`)) / 10 ** coin2.decimals;
}

